const assert = require('node:assert/strict');

const { EventService } = require('../.build/service');

// Builds a Source (see src/source.ts) whose lease records usage and can fail
// its read or close on demand.
function makeSource({ values = [], closeError = null } = {}) {
  const state = { opens: 0, closes: 0, reads: 0 };
  const source = {
    async open() {
      state.opens++;
      return {
        async read() {
          state.reads++;
          return values.length ? values.shift() : null;
        },
        async close() {
          state.closes++;
          if (closeError) throw closeError;
        },
      };
    },
  };
  return { source, state };
}

async function main() {
  // 1. Returning an unopened generator opens or closes nothing.
  {
    const { source, state } = makeSource({ values: ['a'] });
    const gen = new EventService(source).stream();
    assert.equal(state.opens, 0);
    assert.deepEqual(await gen.return(), { value: undefined, done: true });
    assert.equal(state.opens, 0);
    assert.equal(state.closes, 0);
  }

  // 2. Normal exhaustion: ordered mapped values, one read per next plus the
  //    exhaustion read, and exactly one close.
  {
    const { source, state } = makeSource({ values: ['a', 'b'] });
    const gen = new EventService(source).stream();
    assert.equal(state.opens, 0); // not opened before first iteration
    assert.deepEqual(await gen.next(), { value: 'A', done: false });
    assert.equal(state.opens, 1);
    assert.equal(state.reads, 1); // no read ahead
    assert.deepEqual(await gen.next(), { value: 'B', done: false });
    assert.equal(state.reads, 2);
    assert.deepEqual(await gen.next(), { value: undefined, done: true });
    assert.equal(state.reads, 3); // the read establishing exhaustion
    assert.equal(state.closes, 1);
    assert.deepEqual(await gen.next(), { value: undefined, done: true });
    assert.equal(state.closes, 1);
  }

  // 3. for await order and close-once on normal exhaustion.
  {
    const { source, state } = makeSource({ values: ['a', 'b'] });
    const found = [];
    for await (const value of new EventService(source).stream()) found.push(value);
    assert.deepEqual(found, ['A', 'B']);
    assert.equal(state.closes, 1);
    assert.equal(state.reads, 3);
  }

  // 4. Consumer break: lease is closed exactly once.
  {
    const { source, state } = makeSource({ values: ['a', 'b', 'c'] });
    for await (const value of new EventService(source).stream()) {
      assert.equal(value, 'A');
      break;
    }
    assert.equal(state.closes, 1);
  }

  // 5. Direct consumer return mid-stream: lease is closed exactly once, and a
  //    later next does not close again.
  {
    const { source, state } = makeSource({ values: ['a', 'b'] });
    const gen = new EventService(source).stream();
    assert.deepEqual(await gen.next(), { value: 'A', done: false });
    await gen.return();
    assert.equal(state.closes, 1);
    assert.deepEqual(await gen.next(), { value: undefined, done: true });
    assert.equal(state.closes, 1);
  }

  // 6. Read failure: original error is propagated, close happens once.
  {
    const readError = new Error('read failed');
    const { source, state } = makeSource({ closeError: null });
    let reads = 0;
    const failing = {
      async open() {
        state.opens++;
        return {
          async read() {
            reads++;
            throw readError;
          },
          async close() {
            state.closes++;
          },
        };
      },
    };
    const gen = new EventService(failing).stream();
    await assert.rejects(gen.next(), (error) => error === readError);
    assert.equal(state.closes, 1);
    assert.equal(reads, 1);
    assert.deepEqual(await gen.next(), { value: undefined, done: true });
    assert.equal(state.closes, 1);
    void source;
  }

  // 7. Read failure with close failure: the read error is preserved.
  {
    const readError = new Error('read failed');
    const closeError = new Error('close failed');
    const source = {
      async open() {
        return {
          async read() {
            throw readError;
          },
          async close() {
            throw closeError;
          },
        };
      },
    };
    const gen = new EventService(source).stream();
    await assert.rejects(gen.next(), (error) => error === readError);
  }

  // 8. Mapper failure: lease is closed once, original error propagates even
  //    when close also fails.
  {
    const mapperError = new Error('mapper failed');
    const { source, state } = makeSource({ values: ['a'] });
    const gen = new EventService(source, () => {
      throw mapperError;
    }).stream();
    await assert.rejects(gen.next(), (error) => error === mapperError);
    assert.equal(state.closes, 1);

    const closeError = new Error('close failed');
    const failing = makeSource({ values: ['a'], closeError });
    const gen2 = new EventService(failing.source, () => {
      throw mapperError;
    }).stream();
    await assert.rejects(gen2.next(), (error) => error === mapperError);
    assert.equal(failing.state.closes, 1);
  }

  // 9. Consumer-injected throw: lease is closed once and the injected error is
  //    preserved even when close also fails.
  {
    const closeError = new Error('close failed');
    const { source, state } = makeSource({ values: ['a', 'b'], closeError });
    const gen = new EventService(source).stream();
    assert.deepEqual(await gen.next(), { value: 'A', done: false });
    const injected = new Error('injected');
    await assert.rejects(gen.throw(injected), (error) => error === injected);
    assert.equal(state.closes, 1);

    // Injecting into an unopened generator opens nothing.
    const untouched = makeSource({ values: ['a'] });
    const unopened = new EventService(untouched.source).stream();
    await assert.rejects(unopened.throw(injected), (error) => error === injected);
    assert.equal(untouched.state.opens, 0);
    assert.equal(untouched.state.closes, 0);
  }

  // 10. Close failure with no other failure in flight is propagated.
  {
    const closeError = new Error('close failed');
    const { source, state } = makeSource({ values: ['a'], closeError });
    const gen = new EventService(source).stream();
    assert.deepEqual(await gen.next(), { value: 'A', done: false });
    await assert.rejects(gen.next(), (error) => error === closeError);
    assert.equal(state.closes, 1);
  }

  // 11. Consumer break with close failure: the close failure is propagated.
  {
    const closeError = new Error('close failed');
    const { source, state } = makeSource({ values: ['a', 'b'], closeError });
    await assert.rejects(
      (async () => {
        for await (const value of new EventService(source).stream()) {
          assert.equal(value, 'A');
          break;
        }
      })(),
      (error) => error === closeError,
    );
    assert.equal(state.closes, 1);
  }

  // 12. Source open failure: no lease exists, so close is never attempted.
  {
    const openError = new Error('open failed');
    let closes = 0;
    const gen = new EventService({
      async open() {
        throw openError;
      },
    }).stream();
    await assert.rejects(gen.next(), (error) => error === openError);
    assert.equal(closes, 0);
  }

  // 13. Exception thrown by the consumer inside the for-await body (the runtime
  //     then closes the generator) with close failing: the consumer error wins
  //     and the lease is still closed exactly once.
  {
    const closeError = new Error('close failed');
    const consumerError = new Error('consumer failed');
    const { source, state } = makeSource({ values: ['a', 'b'], closeError });
    await assert.rejects(
      (async () => {
        for await (const value of new EventService(source).stream()) {
          assert.equal(value, 'A');
          throw consumerError;
        }
      })(),
      (error) => error === consumerError,
    );
    assert.equal(state.closes, 1);
  }

  // 14. Concurrent return calls close only once.
  {
    const { source, state } = makeSource({ values: ['a'] });
    const gen = new EventService(source).stream();
    await gen.next();
    const results = await Promise.all([gen.return('x'), gen.return('y')]);
    assert.equal(state.closes, 1);
    assert.equal(results[0].done, true);
    assert.equal(results[1].done, true);
  }
}

const run = main();

module.exports = run;

if (require.main === module) {
  run.then(
    () => console.log('service behavior checks passed'),
    (error) => {
      console.error(error);
      process.exitCode = 1;
    },
  );
}

